package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.Bundle;import android.provider.BlockedNumberContract;import android.telephony.PhoneNumberUtils;import android.text.InputType;import android.widget.*;import java.util.*;
/** Operator requests are prepared in the dialer, never sent by opening or selecting this page. */
public final class CallToolsActivity extends LeoActivity {
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 static String forwardCode(String number,boolean enable){if(!enable)return "##21#";String raw=number==null?"":number.trim();if(!raw.matches("[+0-9() .-]+"))throw new IllegalArgumentException();String n=PhoneNumberUtils.normalizeNumber(raw);if(!n.matches("\\+?[0-9]{3,20}"))throw new IllegalArgumentException();return "**21*"+n+"#";}
 private void home(){list(L.t("Servicii de apel"),Arrays.asList(L.t("Numere blocate Android"),L.t("Apel în așteptare"),L.t("Redirecționarea apelurilor"),L.t("Conferință și al doilea apel")),0,new Choice(){public void pick(int n){if(n==0)blocked();else if(n==1)waiting();else if(n==2)forwarding();else explain();}},"",null);}
 private void prepare(String code){startActivity(new Intent(this,PhoneActivity.class).setAction(Intent.ACTION_DIAL).setData(Uri.fromParts("tel",code,null)));notice(L.t("Cerere pregătită · Verde și alegerea SIM-ului o trimit operatorului"));}
 private void waiting(){options(L.t("Apel în așteptare · operator"),new String[]{L.t("Verifică starea · *#43#"),L.t("Activează · *43#"),L.t("Dezactivează · #43#")},new Choice(){public void pick(int n){prepare(new String[]{"*#43#","*43#","#43#"}[n]);}});}
 private void forwarding(){options(L.t("Redirecționare necondiționată"),new String[]{L.t("Verifică starea · *#21#"),L.t("Redirecționează către număr"),L.t("Elimină redirecționarea · ##21#")},new Choice(){public void pick(int n){if(n==0)prepare("*#21#");else if(n==2)prepare("##21#");else{LinearLayout f=fields(L.t("Număr pentru redirecționare"));final EditText number=field(f,L.t("Număr"),"",InputType.TYPE_CLASS_PHONE);left=new Runnable(){public void run(){try{prepare(forwardCode(number.getText().toString(),true));}catch(IllegalArgumentException e){notice(L.t("Număr invalid"));}}};back=new Runnable(){public void run(){home();}};footer(L.t("Pregătește"),"Editor",L.t("Șterge"));number.requestFocus();}}});}
 private void explain(){begin(L.t("Conferință Leo"));ScrollView s=new ScrollView(this);s.addView(text(L.t("În apel: Opțiuni → Adaugă apel deschide Telefon. Alegi numărul și SIM-ul. Telecom și operatorul decid dacă apelul curent poate fi pus în așteptare.\n\nOpțiuni → Apeluri și conferință permite alegerea apelului, unirea apelurilor compatibile sau comutarea conferinței. Acțiunile apar numai când sunt oferite de Telecom. Serviciile de operator nu sunt validate doar prin deschiderea acestei pagini."),16));root.addView(s,new LinearLayout.LayoutParams(-1,0,1));s.setFocusable(true);s.requestFocus();back=new Runnable(){public void run(){home();}};footer("",L.t("Derulează"),L.t("Înapoi"));}
 private void blocked(){worker.execute(new Runnable(){public void run(){final ArrayList<Long> ids=new ArrayList<Long>();final ArrayList<String> labels=new ArrayList<String>();boolean denied=false;try(Cursor r=getContentResolver().query(BlockedNumberContract.BlockedNumbers.CONTENT_URI,new String[]{"_id","original_number"},null,null,"_id DESC")){while(r!=null&&r.moveToNext()&&ids.size()<500){ids.add(r.getLong(0));labels.add(r.getString(1));}}catch(RuntimeException e){denied=true;}final boolean error=denied;ui(new Runnable(){public void run(){list(L.t("Numere blocate Android"),labels,0,new Choice(){public void pick(final int n){options(L.t("Deblochezi numărul?"),new String[]{L.t("Păstrează"),L.t("Deblochează")},new Choice(){public void pick(int yes){if(yes==1)try{getContentResolver().delete(ContentUris.withAppendedId(BlockedNumberContract.BlockedNumbers.CONTENT_URI,ids.get(n)),null,null);blocked();}catch(RuntimeException e){notice(L.t("Blocarea numerelor nu este permisă pentru Leo"));}}});}},L.t("Adaugă"),new Runnable(){public void run(){addBlocked();}});back=new Runnable(){public void run(){home();}};if(error)notice(L.t("Blocarea numerelor nu este permisă pentru Leo"));}});}});}
 private void addBlocked(){LinearLayout f=fields(L.t("Blochează un număr"));final EditText number=field(f,L.t("Număr"),"",InputType.TYPE_CLASS_PHONE);left=new Runnable(){public void run(){final String n=PhoneNumberUtils.normalizeNumber(number.getText().toString());if(!n.matches("\\+?[0-9]{3,20}")){notice(L.t("Număr invalid"));return;}options(n,new String[]{L.t("Anulează"),L.t("Blochează în Android")},new Choice(){public void pick(int yes){if(yes==1)try{ContentValues v=new ContentValues();v.put("original_number",n);if(getContentResolver().insert(BlockedNumberContract.BlockedNumbers.CONTENT_URI,v)==null)throw new IllegalStateException();blocked();}catch(RuntimeException e){notice(L.t("Blocarea numerelor nu este permisă pentru Leo"));}}});}};back=new Runnable(){public void run(){blocked();}};footer(L.t("Continuă"),"Editor",L.t("Șterge"));number.requestFocus();}
}
